#root {
  min-height: 100vh;
}

.date-page {
  box-sizing: border-box;
  display: grid;
  min-height: 100vh;
  padding: 48px 24px;
  place-items: center;
  background: var(--g-color-base-background);
}

.date-panel {
  box-sizing: border-box;
  width: min(100%, 480px);
  padding: 32px;
  border: 1px solid var(--g-color-line-generic);
  border-radius: var(--g-border-radius-xl);
  background: var(--g-color-base-generic);
}

.date-panel__header {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-bottom: 24px;
}

.date-panel__calendar {
  display: flex;
  justify-content: center;
  max-width: 100%;
}

.date-panel__selection {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-top: 24px;
  padding: 16px 20px;
  border-radius: var(--g-border-radius-l);
  background: var(--g-color-base-generic-ultralight);
}

