@use '../variables';

$block: '.#{variables.$ns}calendar';

#{$block} {
    --_--calendar-padding: var(--g-date-calendar-padding, 8px);
    --_--calendar-day-size: var(--g-date-calendar-day-size, 28px);
    --_--calendar-days-gap: var(--g-date-calendar-days-gap, 2px);

    --_--calendar-width: calc(
        7 * var(--_--calendar-day-size) + 6 * var(--_--calendar-days-gap) + 2 *
            var(--_--calendar-padding)
    );
    --_--calendar-grid-height: calc(
        7 * var(--_--calendar-day-size) + 5 * var(--_--calendar-days-gap) +
            var(--_--calendar-padding)
    );

    display: inline-block;

    width: var(--_--calendar-width);

    &_size_l {
        --g-date-calendar-day-size: 36px;
    }

    &_size_xl {
        --g-date-calendar-day-size: 42px;

        @include mixins.text-body-2();
    }

    &__header {
        display: flex;
        justify-content: space-between;

        padding: var(--_--calendar-padding) var(--_--calendar-padding) 0;
    }

    &__years-label {
        color: var(--g-color-text-secondary);
    }

    &__controls {
        display: flex;
        flex-shrink: 1;
        justify-content: flex-end;
        gap: var(--g-spacing-2);
    }

    &__control-icon {
        transform: scaleX(var(--g-flow-direction));
    }

    &__grid {
        position: relative;

        overflow: hidden;

        width: 100%;
        height: var(--_--calendar-grid-height);

        user-select: none;
    }

    &__content {
        position: absolute;
        inset-block-start: 0;
        inset-inline-start: 0;

        display: grid;
        grid-template-rows: var(--_--calendar-day-size) 1fr;

        box-sizing: border-box;
        width: 100%;
        height: 100%;
        padding: 0 var(--_--calendar-padding) var(--_--calendar-padding);

        @keyframes calendar-forward {
            from {
                transform: translateX(0);
            }
            to {
                transform: translateX(100%);
            }
        }

        @keyframes calendar-backward {
            from {
                transform: translateX(0);
            }
            to {
                transform: translateX(-100%);
            }
        }

        @keyframes calendar-zoom-in-showing {
            from {
                opacity: 0;

                transform: scale(2);
            }
            to {
                opacity: 1;

                transform: scale(1);
            }
        }

        @keyframes calendar-zoom-in-hiding {
            from {
                opacity: 1;

                transform: scale(1);
            }
            to {
                opacity: 0;

                transform: scale(0);
            }
        }

        @keyframes calendar-zoom-out-showing {
            from {
                opacity: 0;

                transform: scale(0);
            }
            to {
                opacity: 1;

                transform: scale(1);
            }
        }

        @keyframes calendar-zoom-out-hiding {
            from {
                opacity: 1;

                transform: scale(1);
            }
            to {
                opacity: 0;

                transform: scale(2);
            }
        }

        &_animation_forward {
            transform: translateX(-100%);
            animation: calendar-forward 0.25s ease forwards;

            &#{$block}__current-state {
                inset-inline-start: calc(var(--g-flow-direction) * -100%);
            }
        }

        &_animation_backward {
            transform: translateX(0);
            animation: calendar-backward 0.25s ease forwards;

            &#{$block}__current-state {
                inset-inline-start: calc(var(--g-flow-direction) * 100%);
            }
        }

        &_animation_zoom-in {
            transform: scale();

            &#{$block}__previous-state {
                animation: calendar-zoom-in-hiding 0.25s ease forwards;
            }
            &#{$block}__current-state {
                animation: calendar-zoom-in-showing 0.25s ease forwards;
            }
        }

        &_animation_zoom-out {
            transform: scale();

            &#{$block}__current-state {
                animation: calendar-zoom-out-showing 0.25s ease forwards;
            }
            &#{$block}__previous-state {
                animation: calendar-zoom-out-hiding 0.25s ease forwards;
            }
        }

        @media screen and (prefers-reduced-motion: reduce), (update: slow) {
            &[class] {
                animation-duration: 0.001ms;
            }
        }
    }

    &__grid-rowgroup {
        display: grid;
        gap: var(--_--calendar-days-gap);

        &_mode_months,
        &_mode_quarters,
        &_mode_years {
            grid-row: 1 / -1;

            padding: 12px 0 0;
        }

        &-header {
            align-self: center;
        }
    }

    &__grid-row {
        display: grid;
        grid-auto-columns: 1fr;
        grid-auto-flow: column;
        gap: var(--_--calendar-days-gap);
    }

    &__weekday {
        display: flex;
        justify-content: center;
        align-items: center;

        width: 100%;
        height: 100%;

        &_weekend {
            color: var(--g-color-text-danger);
        }
    }

    &__button {
        $button: &;
        position: relative;

        display: flex;
        justify-content: center;
        align-items: center;

        width: 100%;
        height: 100%;

        font-weight: var(--g-text-subheader-font-weight);
        cursor: pointer;
        text-transform: capitalize;

        border-radius: 4px;
        outline: none;

        &:focus {
            box-shadow: 0 0 0 2px var(--g-color-line-misc);
        }

        &:focus:not(:focus-visible) {
            box-shadow: none;
        }

        &:hover {
            background-color: var(--g-color-base-generic);
        }

        &_selected[class] {
            background-color: var(--g-color-base-selection);
        }
        &_selected#{&}_selection-start,
        &_selected#{&}_selection-end {
            background-color: var(--g-color-base-brand);

            &:not(#{$button}_weekend) {
                color: var(--g-color-text-brand-contrast);
            }
        }

        &_weekend {
            color: var(--g-color-text-danger);
        }

        &_out-of-boundary {
            font-weight: var(--g-text-body-font-weight);

            opacity: 0.6;
        }

        &_current::before {
            position: absolute;
            inset-block-start: 50%;

            display: block;

            width: 4px;
            height: 4px;

            content: '';

            border-radius: 50%;
            background-color: currentColor;

            transform: translateY(8px);
        }

        &_disabled {
            font-weight: var(--g-text-body-font-weight);
            pointer-events: none;

            opacity: 0.6;
        }

        &_unavailable:not(&_disabled) {
            font-weight: var(--g-text-body-font-weight);
            cursor: default;

            opacity: 0.5;
            background-color: var(--g-color-base-generic);
        }
    }

    &__mode-label {
        text-transform: capitalize;
    }
}
","@use 'sass:list';
@use 'sass:selector';

@mixin overflow-ellipsis($type: ellipsis) {
    white-space: nowrap;
    overflow: hidden;
    text-overflow: $type;
}

@mixin button-reset() {
    padding: 0;

    font-family: var(--g-text-body-font-family);
    font-size: inherit;
    font-weight: var(--g-text-body-font-weight);

    color: inherit;
    background: none;
    border: none;
    outline: none;
    cursor: pointer;
}

@mixin link-reset() {
    color: inherit;
    text-decoration: inherit;
}

@mixin expand-interactive-area($h: 4px, $v: $h) {
    position: relative;

    &::after {
        content: '';
        position: absolute;
        inset: logical (-$v) (-$h);
    }
}

@mixin max-height($height) {
    max-height: $height;
    overflow-y: auto;
}

@mixin max-text-width($width: 100%) {
    @include overflow-ellipsis();

    max-width: $width;
}

@mixin aspect-ratio($ratio) {
    position: relative;

    &::before {
        display: block;
        content: '';
        width: 100%;
        padding-block-start: $ratio * 100%;
    }

    > *:only-child {
        position: absolute;
        inset: 0;
    }
}

@function get-pin-selector($mod, $selector, $append: true) {
    @if $append {
        @return selector.append($mod, $selector);
    } @else {
        @return list.join($mod, $selector, $separator: space);
    }
}

@mixin pin($block, $selectors, $radius, $append: true) {
    @each $selector in $selectors {
        @at-root #{get-pin-selector(#{$block}_pin_round-round, $selector, $append)} {
            border-radius: $radius;
        }

        @at-root #{get-pin-selector(#{$block}_pin_brick-brick, $selector, $append)} {
            border-radius: 0;
        }

        @at-root #{get-pin-selector(#{$block}_pin_clear-clear, $selector, $append)} {
            border-radius: 0;
            border-inline: 0;
        }

        @at-root #{get-pin-selector(#{$block}_pin_circle-circle, $selector, $append)} {
            border-radius: 100px;
        }

        @at-root #{get-pin-selector(#{$block}_pin_round-brick, $selector, $append)} {
            border-start-start-radius: $radius;
            border-start-end-radius: 0;
            border-end-start-radius: $radius;
            border-end-end-radius: 0;
        }

        @at-root #{get-pin-selector(#{$block}_pin_brick-round, $selector, $append)} {
            border-start-start-radius: 0;
            border-start-end-radius: $radius;
            border-end-start-radius: 0;
            border-end-end-radius: $radius;
        }

        @at-root #{get-pin-selector(#{$block}_pin_round-clear, $selector, $append)} {
            border-start-start-radius: $radius;
            border-start-end-radius: 0;
            border-end-start-radius: $radius;
            border-end-end-radius: 0;
            border-inline-end: 0;
        }

        @at-root #{get-pin-selector(#{$block}_pin_clear-round, $selector, $append)} {
            border-start-start-radius: 0;
            border-start-end-radius: $radius;
            border-end-start-radius: 0;
            border-end-end-radius: $radius;
            border-inline-start: 0;
        }

        @at-root #{get-pin-selector(#{$block}_pin_brick-clear, $selector, $append)} {
            border-radius: 0;
            border-inline-end: 0;
        }

        @at-root #{get-pin-selector(#{$block}_pin_clear-brick, $selector, $append)} {
            border-radius: 0;
            border-inline-start: 0;
        }

        @at-root #{get-pin-selector(#{$block}_pin_circle-brick, $selector, $append)} {
            border-start-start-radius: 100px;
            border-start-end-radius: 0;
            border-end-start-radius: 100px;
            border-end-end-radius: 0;
        }

        @at-root #{get-pin-selector(#{$block}_pin_brick-circle, $selector, $append)} {
            border-start-start-radius: 0;
            border-start-end-radius: 100px;
            border-end-start-radius: 0;
            border-end-end-radius: 100px;
        }

        @at-root #{get-pin-selector(#{$block}_pin_circle-clear, $selector, $append)} {
            border-start-start-radius: 100px;
            border-start-end-radius: 0;
            border-end-start-radius: 100px;
            border-end-end-radius: 0;
            border-inline-end: 0;
        }

        @at-root #{get-pin-selector(#{$block}_pin_clear-circle, $selector, $append)} {
            border-start-start-radius: 0;
            border-start-end-radius: 100px;
            border-end-start-radius: 0;
            border-end-end-radius: 100px;
            border-inline-start: 0;
        }
    }
}

